// forEach - EFEKT UBOCZNY (console.log), NIC nie zwraca
products.forEach(p => console.log(p.name));
// wynik wywolania forEach to: undefined - nikt go NIE UZYWA

// map - TRANSFORMACJA, zwraca NOWA, uzyteczna tablice
const names = products.map(p => p.name);
console.log(names); // ['Laptop', 'T-shirt', ...] - WYNIK jest wykorzystany

const products = [
  { name: "Laptop", price: 3000 },
  { name: "T-shirt", price: 49 },
];

products.forEach((p, index) => {
  console.log(`${index + 1}. ${p.name} - ${p.price} zl`);
});
// 1. Laptop - 3000 zl
// 2. T-shirt - 49 zl

const products = [
  { name: "Laptop", price: 3000 },
  { name: "T-shirt", price: 49 },
];

const log = [];
products.forEach((p, index) => {
  log.push(`${index + 1}. ${p.name} - ${p.price} zl`);
});

console.log(log); // ['1. Laptop - 3000 zl', '2. T-shirt - 49 zl']

const liczby = [1, 2, 3];
const podwojone = liczby.forEach(n => {
  return n * 2; // TA wartosc jest CALKOWICIE ignorowana przez forEach
});

console.log(podwojone); // undefined - BLEDNIE, NIE [2, 4, 6]

const liczby = [1, 2, 3];
const podwojone = liczby.map(n => n * 2);

console.log(podwojone); // [2, 4, 6] - POPRAWNIE

