const zwierzeta = ["kot", "pies", "papuga"];
zwierzeta.forEach((z, indeks) => {
  console.log(`${indeks}: ${z}`);
});
// 0: kot
// 1: pies
// 2: papuga

const pracownicy = [{ imie: "Marta", wiek: 34 }, { imie: "Tomek", wiek: 19 }];

pracownicy.forEach(p => {
  console.log(`${p.imie} (${p.wiek} lata)`);
});
// Marta (34 lata)
// Tomek (19 lata)

const temperatury = [15, 22, 8, 30, 19];
let suma = 0;

temperatury.forEach(t => {
  suma += t;
});

console.log(suma); // 94

const zadania = ["kupic mleko", "posprzatac", "zadzwonic"];
zadania.forEach(z => console.log(`- ${z}`));
// - kupic mleko
// - posprzatac
// - zadzwonic

const liczby = [1, 2, 3];
const wynik = liczby.forEach(n => {
  return n * 2;
});

console.log(wynik); // undefined - BLEDNIE, forEach() nie buduje nowej tablicy

const liczby = [1, 2, 3];
const podwojone = liczby.map(n => n * 2);

console.log(podwojone); // [2, 4, 6] - POPRAWNIE

const produkty = [
  { nazwa: "Laptop", cena: 3000 },
  { nazwa: "Mysz", cena: 50 },
  { nazwa: "Klawiatura", cena: 150 }
];

const raport = [];
produkty.forEach(p => {
  raport.push(`${p.nazwa}: ${p.cena} zl`);
});

console.log(raport);
// ['Laptop: 3000 zl', 'Mysz: 50 zl', 'Klawiatura: 150 zl']
